INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20F8IRY', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A school district found that students who ate breakfast scored higher on standardized tests than students who did not eat breakfast. The district concludes that eating breakfast causes higher test scores. Which of the following is the most significant flaw in this conclusion?', NULL, $lyceon_json$[{"key":"A","text":"The sample size may have been too small."},{"key":"B","text":"The study was observational, so a cause-and-effect relationship cannot be established."},{"key":"C","text":"Standardized tests are not a valid measure of academic performance."},{"key":"D","text":"The study did not include students from other school districts."}]$lyceon_json$::jsonb, 'B', NULL, E'The study is observational because students were not randomly assigned to eat or skip breakfast. Without random assignment, confounding variables (such as household income, sleep habits, or parental involvement) could explain the association. Observational studies can identify associations but cannot establish causation. While sample size can affect precision, the fundamental issue is the lack of random assignment. Questioning the validity of standardized tests is irrelevant to the study design flaw. Limiting to one district affects generalizability but does not address the causation claim.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20XK4KY', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A machine fills $11$ bottles every $3$ minutes. At this rate, how many bottles does the machine fill in $21$ minutes?', NULL, $lyceon_json$[{"key":"A","text":"$77$"},{"key":"B","text":"$63$"},{"key":"C","text":"$84$"},{"key":"D","text":"$33$"}]$lyceon_json$::jsonb, 'A', NULL, E'The rate is $\\frac{11}{3}$ bottles per minute. In 21 minutes: $\\frac{11}{3} \\times 21 = 77$ bottles.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
