INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21ZU0O5', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following is equivalent to $5(3x - 4) - 2x$?', NULL, $lyceon_json$[{"key":"A","text":"$13x - 20$"},{"key":"B","text":"$13x - 4$"},{"key":"C","text":"$15x - 20$"},{"key":"D","text":"$13x + 20$"}]$lyceon_json$::jsonb, 'A', NULL, E'Distributing gives $5(3x - 4) = 15x - 20$. Combining with $-2x$ yields $15x - 20 - 2x = 13x - 20$. The expression $13x - 4$ results from failing to multiply $-4$ by $5$. The expression $15x - 20$ omits the subtraction of $2x$. The expression $13x + 20$ incorrectly treats $-20$ as positive.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22GB81U', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'A polling organization surveys $900$ randomly selected adults in a state and finds that $53\\%$ favor a new energy policy, with a margin of error of $3.3\\%$ at a $95\\%$ confidence level. A journalist reports: "A majority of adults in the state favor the new energy policy." Which of the following best evaluates the journalist''s claim?', NULL, $lyceon_json$[{"key":"A","text":"The claim is supported because $53\\%$ is greater than $50\\%$."},{"key":"B","text":"The claim is not supported because the confidence interval includes values below $50\\%$."},{"key":"C","text":"The claim is supported because the sample size of $900$ is large enough to eliminate uncertainty."},{"key":"D","text":"The claim is not supported because $95\\%$ confidence means there is a $5\\%$ chance the true value is $0\\%$."}]$lyceon_json$::jsonb, 'B', NULL, E'The $95\\%$ confidence interval is $53\\% \\pm 3.3\\%$, which spans from $49.7\\%$ to $56.3\\%$. Since $49.7\\%$ is below $50\\%$, the interval includes the possibility that fewer than half of all adults favor the policy. The journalist''s claim of a majority is therefore not supported by the data at this confidence level. While $53\\%$ is above $50\\%$ in the sample, the margin of error means the population proportion could plausibly be below $50\\%$. No sample size eliminates uncertainty entirely. The interpretation that $5\\%$ chance corresponds to the true value being $0\\%$ fundamentally mischaracterizes how confidence levels work.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22IVUCO', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'mcq', E'A company tests its products with two independent inspectors. Inspector $P$ detects a defect with probability $0.83$, and Inspector $Q$ detects a defect with probability $0.71$. Both inspectors examine each product independently. If a product has a defect, what is the probability that at least one inspector detects it?', NULL, $lyceon_json$[{"key":"A","text":"$0.9507$"},{"key":"B","text":"$0.5893$"},{"key":"C","text":"$0.7700$"},{"key":"D","text":"$0.0493$"}]$lyceon_json$::jsonb, 'A', NULL, E'The probability that at least one inspector detects the defect equals $1$ minus the probability that neither detects it. The probability that Inspector $P$ misses it is $1 - 0.83 = 0.17$, and the probability that Inspector $Q$ misses it is $1 - 0.71 = 0.29$. Since the inspectors are independent, the probability both miss it is $0.17 \\times 0.29 = 0.0493$. Therefore, the probability at least one detects it is $1 - 0.0493 = 0.9507$. The value $0.5893$ comes from multiplying $0.83 \\times 0.71$, which gives the probability both detect it rather than at least one. The value $0.7700$ results from averaging the two detection probabilities. The value $0.0493$ is the probability that neither inspector detects the defect, not that at least one does.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22Z3O85', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'If $\\frac{5(3x - 4)}{2} - 7 = 13$, what is the value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$3$"},{"key":"C","text":"$5$"},{"key":"D","text":"$\\frac{8}{3}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Adding 7 to both sides gives $\\frac{5(3x - 4)}{2} = 20$. Multiplying by 2 gives $5(3x - 4) = 40$. Dividing by 5 gives $3x - 4 = 8$. Adding 4 gives $3x = 12$, so $x = 4$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM236799M', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'mcq', E'What is one solution to $x^2 + 3x - 28 = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$-28$"},{"key":"B","text":"$-4$"},{"key":"C","text":"$4$"},{"key":"D","text":"$7$"}]$lyceon_json$::jsonb, 'C', NULL, E'Factoring: $x^2 + 3x - 28 = (x + 7)(x - 4) = 0$, so $x = -7$ or $x = 4$. The value $4$ is one of the two solutions. The value $-4$ applies the wrong sign to the factor $(x - 4)$. The value $7$ uses the magnitude from $(x + 7)$ but drops the negative sign. The value $-28$ is simply the constant term from the equation, not a root.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23HSG0T', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A line of best fit for a data set is given by $y = 2.3x + 4.1$, where $x$ represents the number of weeks and $y$ represents the height of a plant in centimeters. A data point at $x = 7$ has an actual $y$-value of $19.8$. What is the residual for this data point?', NULL, $lyceon_json$[{"key":"A","text":"$-0.4$"},{"key":"B","text":"$-0.2$"},{"key":"C","text":"$0.2$"},{"key":"D","text":"$0.4$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $-0.4$. The predicted value at $x = 7$ is $y = 2.3(7) + 4.1 = 16.1 + 4.1 = 20.2$. The residual is the actual value minus the predicted value: $19.8 - 20.2 = -0.4$. A negative residual indicates the actual height is below what the model predicted. The answer $-0.2$ results from an arithmetic slip in computing the predicted value. The answer $0.2$ and $0.4$ result from reversing the subtraction order (predicted minus actual instead of actual minus predicted).', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23K3CSZ', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'mcq', E'A solid is formed by removing a cone from a cylinder. The cylinder has a radius of $7$ cm and a height of $10$ cm. The cone has the same base and height as the cylinder. What is the volume of the remaining solid?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{490\\pi}{3}$"},{"key":"B","text":"$\\frac{980\\pi}{3}$"},{"key":"C","text":"$490\\pi$"},{"key":"D","text":"$\\frac{1960\\pi}{3}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The volume of the cylinder is $\\pi r^2 h = \\pi(7^2)(10) = 490\\pi$. The volume of the cone is $\\frac{1}{3}\\pi r^2 h = \\frac{490\\pi}{3}$. The remaining solid has volume $490\\pi - \\frac{490\\pi}{3} = \\frac{1470\\pi - 490\\pi}{3} = \\frac{980\\pi}{3}$. The value $\\frac{490\\pi}{3}$ is the volume of the removed cone, not the remaining solid. The value $490\\pi$ is the full cylinder volume without any subtraction. The value $\\frac{1960\\pi}{3}$ results from adding the cylinder and cone volumes instead of subtracting.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23LMALQ', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'grid_in', E'At what positive value of $x$ do the graphs of $y = x^2 - 3x + 1$ and $y = x + 6$ intersect?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5', ARRAY['5'], E'Setting the expressions equal: $x^2 - 3x + 1 = x + 6$. Rearranging gives $x^2 - 4x - 5 = 0$. Factoring: $(x - 5)(x + 1) = 0$, so $x = 5$ or $x = -1$. Since the question asks for the positive value, $x = 5$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM245DYEA', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $f(x) = -2(x - 7)^2 + 13$ models a projectile''s height in meters. What is the maximum height, in meters, reached by the projectile?', NULL, $lyceon_json$[{"key":"A","text":"$-85$"},{"key":"B","text":"$7$"},{"key":"C","text":"$13$"},{"key":"D","text":"$-13$"}]$lyceon_json$::jsonb, 'C', NULL, E'The function is in vertex form $f(x) = a(x - h)^2 + k$ with $a = -2$, $h = 7$, and $k = 13$. Since $a < 0$, the parabola opens downward and the vertex $(7, 13)$ is the maximum. The maximum height is $13$ meters. The value $7$ is the $x$-coordinate of the vertex (when the maximum occurs), not the maximum height itself. The value $-13$ incorrectly negates the maximum. The value $-85$ equals $f(0) = -2(49) + 13 = -85$, which is the function''s value at $x = 0$, not the maximum.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24G651A', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'mcq', E'In triangle $ABC$, point $D$ lies on side $\\overline{AC}$ such that $\\overline{BD}$ bisects angle $B$. If $AB = 15$, $BC = 21$, and $AC = 24$, what is the length of $\\overline{AD}$?', NULL, $lyceon_json$[{"key":"A","text":"$10$"},{"key":"B","text":"$12$"},{"key":"C","text":"$14$"},{"key":"D","text":"$15$"}]$lyceon_json$::jsonb, 'A', NULL, E'By the angle bisector theorem, the bisector from vertex $B$ divides the opposite side in the ratio of the adjacent sides: $\\frac{AD}{DC} = \\frac{AB}{BC} = \\frac{15}{21} = \\frac{5}{7}$. Since $AD + DC = 24$, setting $AD = 5k$ and $DC = 7k$ gives $12k = 24$, so $k = 2$ and $AD = 10$. The value $12$ results from assuming the bisector divides $\\overline{AC}$ into two equal segments ($24 \\div 2 = 12$), which only holds for an isosceles triangle. The value $14$ results from inverting the ratio as $\\frac{AD}{DC} = \\frac{BC}{AB} = \\frac{7}{5}$, giving $AD = 24 \\times \\frac{7}{12} = 14$. The value $15$ comes from confusing the length of $AD$ with the length of side $AB$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24LPZAF', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'A scatterplot shows a strong positive linear association between the number of hours spent studying and the score on a quiz. Which of the following best describes this association?', NULL, $lyceon_json$[{"key":"A","text":"As the number of hours spent studying increases, the quiz score tends to decrease."},{"key":"B","text":"As the number of hours spent studying increases, the quiz score tends to increase."},{"key":"C","text":"There is no consistent pattern between hours spent studying and quiz score."},{"key":"D","text":"As the number of hours spent studying increases, the quiz score remains constant."}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is that as the number of hours spent studying increases, the quiz score tends to increase. A strong positive linear association means that as one variable increases, the other also tends to increase. The description of a decrease confuses positive with negative association. The claim of no consistent pattern contradicts the stated strong association. The claim that the score remains constant describes no association at all.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM259NS7Z', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'mcq', E'A company''s total cost, in dollars, for producing $n$ units of a product is modeled by the function $C(n) = 37n + 1{,}450$. Due to new regulations, the fixed costs increase by $290$ dollars and the per-unit cost decreases by $4$ dollars. Which function $D(n)$ correctly models the new total cost?', NULL, $lyceon_json$[{"key":"A","text":"$D(n) = 33n + 1{,}740$"},{"key":"B","text":"$D(n) = 41n + 1{,}160$"},{"key":"C","text":"$D(n) = 33n + 1{,}160$"},{"key":"D","text":"$D(n) = 41n + 1{,}740$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $D(n) = 33n + 1{,}740$. The original per-unit cost is $37$ dollars, and it decreases by $4$, giving a new per-unit cost of $37 - 4 = 33$ dollars. The original fixed cost is $1{,}450$ dollars, and it increases by $290$, giving a new fixed cost of $1{,}450 + 290 = 1{,}740$ dollars. The function $D(n) = 41n + 1{,}160$ reverses both changes: adding $4$ to the per-unit cost and subtracting $290$ from the fixed cost. The function $D(n) = 33n + 1{,}160$ correctly decreases the per-unit cost but incorrectly decreases the fixed cost. The function $D(n) = 41n + 1{,}740$ correctly increases the fixed cost but incorrectly increases the per-unit cost.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25JRYJQ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'A pharmaceutical company tested a new migraine medication. They recruited $500$ volunteers who suffer from migraines and randomly assigned $250$ to receive the medication and $250$ to receive a placebo. Neither the participants nor the administering doctors knew which treatment each participant received. After $12$ weeks, $67\\%$ of the medication group and $41\\%$ of the placebo group reported fewer migraines. Which of the following conclusions is best supported by the study design?', NULL, $lyceon_json$[{"key":"A","text":"The medication caused a reduction in migraines among the study participants."},{"key":"B","text":"The medication will reduce migraines for all adults who suffer from migraines."},{"key":"C","text":"The medication is more effective than all existing migraine treatments."},{"key":"D","text":"Volunteers who suffer from migraines are healthier than the general population."}]$lyceon_json$::jsonb, 'A', NULL, E'The study is a double-blind randomized controlled experiment: participants were randomly assigned to treatment or placebo, and neither participants nor doctors knew the assignments. Random assignment supports a causal conclusion, and the double-blind design controls for placebo effects and observer bias. Therefore, the study supports that the medication caused fewer migraines among participants. Generalizing to all adults goes beyond the study''s scope, since volunteers may not represent the broader population. The study compared the medication to a placebo, not to other treatments, so no comparison to existing treatments can be drawn. The claim about volunteer health is unrelated to anything measured in the study.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25KMQWR', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'In triangle $PQR$, the measure of angle $P$ is $37^\\circ$ and the measure of angle $Q$ is $86^\\circ$. What is the measure, in degrees, of angle $R$?', NULL, $lyceon_json$[{"key":"A","text":"$53$"},{"key":"B","text":"$57$"},{"key":"C","text":"$67$"},{"key":"D","text":"$143$"}]$lyceon_json$::jsonb, 'B', NULL, E'The sum of the interior angles of any triangle is $180^\\circ$. Therefore, the measure of angle $R$ is $180 - 37 - 86 = 57^\\circ$. The value $53$ results from an arithmetic error in adding $37 + 86$ as $127$ instead of $123$. The value $67$ results from misreading $37^\\circ$ as $27^\\circ$ and computing $180 - 86 - 27 = 67$. The value $143$ comes from subtracting only angle $P$ from $180$, giving $180 - 37 = 143$, an incomplete calculation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 35, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26KK45J', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'What is the $y$-intercept of the line $4x + 7y = 28$?', NULL, $lyceon_json$[{"key":"A","text":"$(0, 4)$"},{"key":"B","text":"$(0, 7)$"},{"key":"C","text":"$(7, 0)$"},{"key":"D","text":"$(0, 28)$"}]$lyceon_json$::jsonb, 'A', NULL, E'Setting $x = 0$ gives $7y = 28$, so $y = 4$. The $y$-intercept is $(0, 4)$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM278WTNR', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'A scientist models the population of a bacterial colony using $P(t) = 800 \\cdot 2^{t/3}$, where $t$ is measured in hours. By what factor does the population increase every $9$ hours?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$6$"},{"key":"C","text":"$8$"},{"key":"D","text":"$512$"}]$lyceon_json$::jsonb, 'C', NULL, E'The growth factor over $9$ hours is $\\frac{P(t + 9)}{P(t)} = \\frac{800 \\cdot 2^{(t+9)/3}}{800 \\cdot 2^{t/3}} = 2^{9/3} = 2^3 = 8$. The value $3$ equals the exponent $9/3$ itself, not the result of raising $2$ to that power. The value $6$ results from multiplying $2 \\times 3$ instead of computing $2^3$. The value $512$ equals $2^9$, which uses $9$ as the exponent directly instead of dividing by the period of $3$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27H3D4N', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'mcq', E'A line passes through the points $(-2, 11)$ and $(4, -7)$. Which of the following is the equation of this line?', NULL, $lyceon_json$[{"key":"A","text":"$y = -3x + 5$"},{"key":"B","text":"$y = 3x + 17$"},{"key":"C","text":"$y = -3x - 7$"},{"key":"D","text":"$y = 3x + 5$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $y = -3x + 5$. First find the slope: $m = \\frac{-7 - 11}{4 - (-2)} = \\frac{-18}{6} = -3$. Using point-slope form with $(-2, 11)$: $y - 11 = -3(x + 2)$, so $y = -3x - 6 + 11 = -3x + 5$. The equation $y = 3x + 17$ results from using a positive slope of $3$ instead of $-3$. The equation $y = -3x - 7$ comes from an arithmetic error when computing the $y$-intercept. The equation $y = 3x + 5$ uses the wrong sign for the slope while getting the correct intercept by coincidence.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM281CG3G', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'The function $g(x) = 13x - 29$ models the number of widgets produced after $x$ hours. What does the value $13$ represent in this context?', NULL, $lyceon_json$[{"key":"A","text":"The number of widgets produced per hour"},{"key":"B","text":"The total number of widgets produced after 1 hour"},{"key":"C","text":"The number of widgets produced before any hours pass"},{"key":"D","text":"The number of hours needed to produce one widget"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is that $13$ represents the number of widgets produced per hour. In a linear function of the form $g(x) = mx + b$, the coefficient $m$ represents the rate of change. Here, $13$ is the slope, meaning $13$ widgets are produced for each additional hour. The total after 1 hour would be $g(1) = 13(1) - 29 = -16$, which is different from $13$ alone. The value produced before any hours pass is $g(0) = -29$, which is the $y$-intercept, not the slope. The number of hours per widget would be $\\frac{1}{13}$, the reciprocal of the rate.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM291TK3I', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'A shipping company charges a flat fee of 7 dollars plus 3 dollars per pound for each package. A customer has at most 34 dollars to spend on shipping a single package. Which inequality represents all possible weights $w$, in pounds, the customer can ship?', NULL, $lyceon_json$[{"key":"A","text":"$3w + 7 \\leq 34$"},{"key":"B","text":"$3w + 7 \\geq 34$"},{"key":"C","text":"$7w + 3 \\leq 34$"},{"key":"D","text":"$3w - 7 \\leq 34$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total shipping cost is the flat fee of 7 dollars plus 3 dollars per pound, giving a total of $3w + 7$. Since the customer can spend at most 34 dollars, the cost must be less than or equal to 34, yielding $3w + 7 \\leq 34$. The inequality $3w + 7 \\geq 34$ reverses the direction, which would represent spending at least 34 dollars rather than at most. The expression $7w + 3 \\leq 34$ swaps the per-pound rate and the flat fee, misidentifying which value is multiplied by weight. The inequality $3w - 7 \\leq 34$ incorrectly subtracts the flat fee instead of adding it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29E6CLH', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'mcq', E'The mean of six numbers is $14$. When a seventh number is added, the mean of all seven numbers becomes $17$. What is the seventh number?', NULL, $lyceon_json$[{"key":"A","text":"$21$"},{"key":"B","text":"$31$"},{"key":"C","text":"$35$"},{"key":"D","text":"$38$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is $35$. The sum of the original six numbers is $6 \\times 14 = 84$. The sum of all seven numbers is $7 \\times 17 = 119$. The seventh number is $119 - 84 = 35$. The answer $21$ comes from finding the difference in means ($17 - 14 = 3$) and multiplying by $7$, a partial-reasoning error. The answer $31$ results from an arithmetic slip when subtracting $84$ from $119$. The answer $38$ comes from incorrectly computing $7 \\times 17 = 119$ and subtracting only $6 \\times 13.5$ instead of $6 \\times 14$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BUGXMK', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'If $\\frac{4x^3 - 18x^2 + 8x}{2x} = ax^2 + bx + c$ for all $x \\neq 0$, what is the value of $a + b + c$?', NULL, $lyceon_json$[{"key":"A","text":"$-7$"},{"key":"B","text":"$-3$"},{"key":"C","text":"$1$"},{"key":"D","text":"$-6$"}]$lyceon_json$::jsonb, 'B', NULL, E'Dividing each term by $2x$: $\\frac{4x^3}{2x} = 2x^2$, $\\frac{-18x^2}{2x} = -9x$, and $\\frac{8x}{2x} = 4$. So $a = 2$, $b = -9$, and $c = 4$, giving $a + b + c = 2 + (-9) + 4 = -3$. The value $-7$ results from computing only $a + b = 2 + (-9)$ and omitting $c$. The value $1$ results from incorrectly dividing $8x$ by $2x$ as $8$ rather than $4$, giving $2 - 9 + 8 = 1$. The value $-6$ results from adding the original coefficients $4 + (-18) + 8$ without dividing by $2x$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2D8R88J', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'mcq', E'After a $12\\%$ increase, the population of a town is $8{,}960$. What was the population before the increase?', NULL, $lyceon_json$[{"key":"A","text":"$7{,}885$"},{"key":"B","text":"$8{,}000$"},{"key":"C","text":"$8{,}045$"},{"key":"D","text":"$8{,}525$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $8{,}000$. If the original population is $p$, then $1.12p = 8{,}960$, so $p = \\frac{8{,}960}{1.12} = 8{,}000$. The answer $7{,}885$ results from an arithmetic slip when dividing. The answer $8{,}045$ comes from computing $8{,}960 - 0.12 \\times 8{,}960 = 7{,}884.8$ and then rounding incorrectly, confusing forward and reverse percentage operations. The answer $8{,}525$ comes from subtracting a flat amount rather than reversing the percentage increase correctly.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DIG1ND', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'grid_in', E'A researcher collects data on the age of a tree, $x$ (in years), and its trunk diameter, $y$ (in inches). The line of best fit is $y = 0.31x + 2.4$. For a tree that is $47$ years old, the model predicts a trunk diameter of $17.0$ inches, but the actual diameter is $18.9$ inches. What is the residual for this observation?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '1.9', ARRAY['19/10', '1.9'], E'The residual is defined as the actual value minus the predicted value: $18.9 - 17.0 = 1.9$ inches. A positive residual indicates the actual trunk diameter is greater than what the model predicted. Note that $0.31(47) + 2.4 = 14.57 + 2.4 = 16.97 \\approx 17.0$, confirming the predicted value. A common error is computing predicted minus actual, which gives $-1.9$, reversing the sign of the residual.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FFSFOL', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'What is the radius of the circle with equation $x^2 + y^2 - 14x + 8y + 40 = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$5$"},{"key":"B","text":"$2\\sqrt{10}$"},{"key":"C","text":"$\\sqrt{65}$"},{"key":"D","text":"$25$"}]$lyceon_json$::jsonb, 'A', NULL, E'Completing the square: $(x^2 - 14x + 49) + (y^2 + 8y + 16) = -40 + 49 + 16$, which gives $(x - 7)^2 + (y + 4)^2 = 25$. The radius is $\\sqrt{25} = 5$. The value $2\\sqrt{10}$ comes from taking $\\sqrt{40}$ (using the constant term directly without completing the square). The value $\\sqrt{65}$ results from adding the completed-square constants $49 + 16 = 65$ but forgetting to subtract the original constant $40$. The value $25$ confuses the radius squared with the radius itself.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FTRRU2', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'grid_in', E'A plumber charges a flat fee of $47 for a house call plus $31 per hour of labor. An electrician charges a flat fee of $83 plus $22 per hour. After how many hours of work will the plumber and electrician charge the same total amount?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '4', ARRAY['4'], E'Set the two cost expressions equal: $47 + 31h = 83 + 22h$. Subtract $22h$ from both sides: $47 + 9h = 83$. Subtract $47$ from both sides: $9h = 36$. Divide both sides by $9$: $h = 4$. At $4$ hours, both charge $47 + 31(4) = 171$ dollars, confirming the answer.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GJJB99', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'grid_in', E'A right triangular prism has a base that is a right triangle with legs of length $7$ and $11$. If the height of the prism is $6$, what is the volume of the prism?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '231', ARRAY['231'], E'The base of the prism is a right triangle with legs $7$ and $11$. The area of this triangle is $\\frac{1}{2} \\times 7 \\times 11 = \\frac{77}{2}$. The volume of a prism is the base area times the height: $\\frac{77}{2} \\times 6 = 231$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GXHBWY', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A researcher surveys a random sample of $400$ households in a county and finds that the mean monthly electricity bill is $137$ dollars with a margin of error of $9$ dollars. A second random sample of $1{,}600$ households from the same county is taken using the same method. Which of the following is the most likely margin of error for the second sample?', NULL, $lyceon_json$[{"key":"A","text":"$2.25$ dollars"},{"key":"B","text":"$4.50$ dollars"},{"key":"C","text":"$9$ dollars"},{"key":"D","text":"$18$ dollars"}]$lyceon_json$::jsonb, 'B', NULL, E'The margin of error is inversely proportional to the square root of the sample size. The second sample is $4$ times as large ($1{,}600 / 400 = 4$), so the margin of error is divided by $\\sqrt{4} = 2$, giving $9 / 2 = 4.50$ dollars. The value $2.25$ dollars results from dividing by $4$ instead of $\\sqrt{4}$, confusing proportional and square-root relationships. The value $9$ dollars assumes sample size has no effect on margin of error. The value $18$ dollars incorrectly multiplies the margin of error by $2$, reversing the relationship between sample size and precision.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GY46GY', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'mcq', E'A data set of $9$ values has a mean of $23$ and a median of $19$. If the value $19$ is removed from the data set, which of the following must be true about the remaining $8$ values?', NULL, $lyceon_json$[{"key":"A","text":"The mean is less than $23$."},{"key":"B","text":"The mean is greater than $23$."},{"key":"C","text":"The median is $19$."},{"key":"D","text":"The median is greater than $19$."}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is that the mean is greater than $23$. The sum of all $9$ values is $9 \\times 23 = 207$. Removing the value $19$ leaves a sum of $207 - 19 = 188$ for $8$ values, giving a new mean of $\\frac{188}{8} = 23.5$, which is greater than $23$. Since $19$ is below the original mean, removing it increases the mean. The claim that the mean is less than $23$ reverses the direction of this effect. The claims about the median cannot be guaranteed: the new median depends on the specific arrangement of the remaining values, so neither claim about the median must be true.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2H80YQU', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'A survey of $200$ students found that $74$ play soccer, $58$ play tennis, and $19$ play both soccer and tennis. If a student is chosen at random from those who play soccer, what is the probability that the student also plays tennis?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{19}{200}$"},{"key":"B","text":"$\\frac{19}{74}$"},{"key":"C","text":"$\\frac{19}{58}$"},{"key":"D","text":"$\\frac{55}{74}$"}]$lyceon_json$::jsonb, 'B', NULL, E'This is a conditional probability question. Given that the student plays soccer, the sample space is the $74$ soccer players. Of those, $19$ also play tennis, so the conditional probability is $\\frac{19}{74}$. Using $\\frac{19}{200}$ treats the denominator as all students rather than restricting to soccer players. Using $\\frac{19}{58}$ incorrectly conditions on tennis players instead of soccer players. The value $\\frac{55}{74}$ gives the probability of playing soccer but NOT tennis, which answers the complementary question.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HVV5AS', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'What is the value of $x$ in the equation $6x + 11 = 47$?', NULL, $lyceon_json$[{"key":"A","text":"$6$"},{"key":"B","text":"$7$"},{"key":"C","text":"$5$"},{"key":"D","text":"$8$"}]$lyceon_json$::jsonb, 'A', NULL, E'Subtracting 11 from both sides gives $6x = 36$. Dividing by 6 gives $x = 6$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IIZ6JB', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'In triangle $ABC$, side $\\overline{BC}$ is extended through $C$ to point $D$. If the measure of angle $A$ is $43^\\circ$ and the measure of angle $B$ is $71^\\circ$, what is the measure, in degrees, of exterior angle $ACD$?', NULL, $lyceon_json$[{"key":"A","text":"$66$"},{"key":"B","text":"$109$"},{"key":"C","text":"$114$"},{"key":"D","text":"$137$"}]$lyceon_json$::jsonb, 'C', NULL, E'By the exterior angle theorem, an exterior angle of a triangle equals the sum of the two non-adjacent interior angles. Therefore, exterior angle $ACD = 43 + 71 = 114^\\circ$. The value $66$ is the interior angle $C$ itself ($180 - 43 - 71 = 66$), not the exterior angle. The value $109$ results from incorrectly adding angle $A$ and interior angle $C$ ($43 + 66 = 109$) instead of the two remote interior angles. The value $137$ comes from subtracting only angle $A$ from $180$ ($180 - 43 = 137$), accounting for just one remote interior angle.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IOP2RB', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'A data set consists of the values $3, 7, 7, 11, 17$. What is the median of this data set?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$7$"},{"key":"C","text":"$9$"},{"key":"D","text":"$11$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $7$. The data set has $5$ values already in order: $3, 7, 7, 11, 17$. The median is the middle value, which is the $3$rd value: $7$. The answer $3$ comes from selecting the first value instead of the middle one. The answer $9$ results from computing the mean of the entire data set, confusing median with mean. The answer $11$ comes from selecting the $4$th value rather than the $3$rd.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"graph_read_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JGM2AU', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'Line $p$ has the equation $9x - 4y = 26$. Line $q$ is perpendicular to line $p$ and passes through the point $(3, -1)$. What is the $y$-intercept of line $q$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{1}{3}$"},{"key":"B","text":"$-\\frac{1}{3}$"},{"key":"C","text":"$\\frac{23}{9}$"},{"key":"D","text":"$-\\frac{7}{9}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $\\frac{1}{3}$. Rewrite line $p$ in slope-intercept form: $9x - 4y = 26$ becomes $y = \\frac{9}{4}x - \\frac{26}{4}$, so the slope of $p$ is $\\frac{9}{4}$. The slope of a perpendicular line is $-\\frac{4}{9}$. Using point-slope form with $(3, -1)$: $y + 1 = -\\frac{4}{9}(x - 3)$, so $y = -\\frac{4}{9}x + \\frac{12}{9} - 1 = -\\frac{4}{9}x + \\frac{4}{3} - 1 = -\\frac{4}{9}x + \\frac{1}{3}$. The $y$-intercept is $\\frac{1}{3}$. The value $-\\frac{1}{3}$ results from a sign error in the calculation. The value $\\frac{23}{9}$ comes from using the same slope as $p$ (not the perpendicular), confusing perpendicular with parallel. The value $-\\frac{7}{9}$ results from an arithmetic slip when simplifying $\\frac{12}{9} - 1$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KJVH7S', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'grid_in', E'A theater sells adult tickets for 13 dollars each and child tickets for 8 dollars each. On a certain evening, 47 tickets were sold for a total of 486 dollars. How many adult tickets were sold that evening?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '22', ARRAY['22'], E'Let $a$ represent the number of adult tickets and $c$ represent the number of child tickets. The system of equations is $a + c = 47$ and $13a + 8c = 486$. From the first equation, $c = 47 - a$. Substituting into the second equation: $13a + 8(47 - a) = 486$, which gives $13a + 376 - 8a = 486$, so $5a = 110$ and $a = 22$. Verification: with 22 adult tickets and 25 child tickets, the total is $22 + 25 = 47$ tickets and the revenue is $22(13) + 25(8) = 286 + 200 = 486$ dollars.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KVOUAM', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $f(x) = 250(1.07)^x$ models the value, in dollars, of an investment after $x$ years. What is the initial value of the investment, in dollars?', NULL, $lyceon_json$[{"key":"A","text":"$1.07$"},{"key":"B","text":"$17.50$"},{"key":"C","text":"$250$"},{"key":"D","text":"$267.50$"}]$lyceon_json$::jsonb, 'C', NULL, E'The initial value is $f(0) = 250(1.07)^0 = 250(1) = 250$ dollars. The value $1.07$ is the growth factor per year, not the initial value. The value $17.50$ equals $250 \\times 0.07$, which is the dollar increase in the first year, not the starting amount. The value $267.50$ equals $250 \\times 1.07$, which is the value after $1$ year rather than at time $0$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
