INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LZMXQV', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'grid_in', E'A car travels $187$ miles using $8.5$ gallons of gasoline. A truck travels $143$ miles using $11$ gallons of gasoline. How many more miles per gallon does the car get than the truck?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '9', ARRAY['9'], E'The car''s fuel efficiency is $\\frac{187}{8.5} = 22$ miles per gallon. The truck''s fuel efficiency is $\\frac{143}{11} = 13$ miles per gallon. The difference is $22 - 13 = 9$ miles per gallon. A common error is subtracting the distances ($187 - 143 = 44$) or the gallons ($11 - 8.5 = 2.5$) separately rather than comparing the rates. Another error is computing only one vehicle''s efficiency and reporting that as the answer.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MH5MT4', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A shirt originally costs $45$ dollars. During a sale, the price is reduced by $20\\%$. What is the sale price, in dollars?', NULL, $lyceon_json$[{"key":"A","text":"$25$"},{"key":"B","text":"$36$"},{"key":"C","text":"$40$"},{"key":"D","text":"$54$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $36$ dollars. A $20\\%$ reduction means the discount is $0.20 \\times 45 = 9$ dollars, so the sale price is $45 - 9 = 36$ dollars. The answer $25$ results from subtracting $20$ from $45$ instead of computing $20\\%$ of $45$. The answer $40$ comes from an arithmetic error in finding $20\\%$ of $45$. The answer $54$ results from adding $20\\%$ to the original price instead of subtracting it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2N8RMTH', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'grid_in', E'A circle has a radius of $15$. A central angle subtends an arc whose length is $7\\pi$. What is the measure of the central angle, in degrees?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '84', ARRAY['84'], E'The arc length formula is $s = \\frac{\\theta}{360} \\times 2\\pi r$, where $\\theta$ is the central angle in degrees. Substituting: $7\\pi = \\frac{\\theta}{360} \\times 2\\pi(15) = \\frac{30\\pi\\theta}{360} = \\frac{\\pi\\theta}{12}$. Dividing both sides by $\\pi$: $7 = \\frac{\\theta}{12}$. Therefore $\\theta = 84^\\circ$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ND4LQ2', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'mcq', E'In right triangle $ABC$ with the right angle at $B$, point $D$ is the foot of the altitude from $B$ to hypotenuse $\\overline{AC}$. If $AD = 4$ and $DC = 16$, what is the length of $\\overline{BD}$?', NULL, $lyceon_json$[{"key":"A","text":"$8$"},{"key":"B","text":"$4\\sqrt{5}$"},{"key":"C","text":"$10$"},{"key":"D","text":"$4\\sqrt{17}$"}]$lyceon_json$::jsonb, 'A', NULL, E'When an altitude is drawn from the right angle to the hypotenuse of a right triangle, the altitude is the geometric mean of the two segments of the hypotenuse. Therefore $BD^2 = AD \\times DC = 4 \\times 16 = 64$, giving $BD = 8$. The value $4\\sqrt{5}$ equals $\\sqrt{AD \\times AC} = \\sqrt{4 \\times 20} = \\sqrt{80}$, which is the length of leg $\\overline{AB}$, not the altitude. The value $10$ results from taking the arithmetic mean $\\frac{4 + 16}{2} = 10$ instead of the geometric mean. The value $4\\sqrt{17}$ results from incorrectly applying the Pythagorean theorem as $\\sqrt{4^2 + 16^2} = \\sqrt{272} = 4\\sqrt{17}$, treating $AD$ and $DC$ as legs of a right triangle.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NTSX74', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'grid_in', E'In right triangle $RST$, angle $T = 90^\\circ$. If $\\tan(R) = \\frac{7}{4}$ and $RT = 12$, what is the length of side $\\overline{ST}$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '21', ARRAY['21'], E'In right triangle $RST$ with the right angle at $T$, side $\\overline{ST}$ is opposite angle $R$ and side $\\overline{RT}$ is adjacent to angle $R$. Therefore $\\tan(R) = \\frac{ST}{RT}$. Substituting the given values: $\\frac{7}{4} = \\frac{ST}{12}$. Solving gives $ST = 12 \\times \\frac{7}{4} = 21$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OA6H13', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A triangle has a base of $18$ centimeters and a height of $11$ centimeters. What is the area of the triangle, in square centimeters?', NULL, $lyceon_json$[{"key":"A","text":"$90$"},{"key":"B","text":"$99$"},{"key":"C","text":"$108$"},{"key":"D","text":"$198$"}]$lyceon_json$::jsonb, 'B', NULL, E'The area of a triangle is $\\frac{1}{2} \\times \\text{base} \\times \\text{height} = \\frac{1}{2} \\times 18 \\times 11 = 99$ square centimeters. The value $90$ results from an arithmetic slip, computing $\\frac{1}{2} \\times 18 \\times 10 = 90$ instead of using $11$. The value $108$ results from another arithmetic slip, computing $\\frac{1}{2} \\times 18 \\times 12 = 108$. The value $198$ comes from computing $18 \\times 11 = 198$ without applying the $\\frac{1}{2}$ factor in the triangle area formula.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 35, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QNAPTE', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which expression is equivalent to $\\frac{16x^4 - 81}{4x^2 + 9}$?', NULL, $lyceon_json$[{"key":"A","text":"$4x^2 - 9$"},{"key":"B","text":"$4x^2 + 9$"},{"key":"C","text":"$4x^2 - 81$"},{"key":"D","text":"$16x^2 - 9$"}]$lyceon_json$::jsonb, 'A', NULL, E'The numerator is a difference of squares: $16x^4 - 81 = (4x^2)^2 - 9^2 = (4x^2 - 9)(4x^2 + 9)$. Dividing by $4x^2 + 9$ gives $4x^2 - 9$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QNDKDL', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'Researchers want to test whether a new fertilizer increases tomato yield. They randomly assign $34$ identical greenhouse plots to receive either the new fertilizer or a standard fertilizer and measure the yield after $60$ days. Which of the following best describes why random assignment is used in this study?', NULL, $lyceon_json$[{"key":"A","text":"To ensure that the researchers do not know which plots receive which fertilizer"},{"key":"B","text":"To make the results generalizable to all types of crops"},{"key":"C","text":"To reduce the effect of confounding variables by distributing them evenly across the two groups"},{"key":"D","text":"To guarantee that the new fertilizer will produce a measurable difference in yield"}]$lyceon_json$::jsonb, 'C', NULL, E'Random assignment distributes potential confounding variables (such as soil quality variation, sunlight exposure, or moisture differences) approximately evenly across the treatment and control groups. This allows researchers to attribute differences in yield to the fertilizer rather than to lurking variables. Concealing treatment assignment from researchers describes blinding, not random assignment. Generalizability to other crops depends on the scope of the study design and replication, not on random assignment within this experiment. No experimental design can guarantee a measurable difference — random assignment enables valid causal inference if a difference is observed.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RZT5EP', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'grid_in', E'A store marks up the wholesale price of an item by $40\\%$ to set the retail price. During a clearance event, the retail price is then reduced by $25\\%$. If the clearance price of the item is $63$ dollars, what was the wholesale price, in dollars?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '60', ARRAY['60'], E'Let the wholesale price be $w$. The retail price after a $40\\%$ markup is $1.4w$. The clearance price after a $25\\%$ reduction is $0.75 \\times 1.4w = 1.05w$. Setting $1.05w = 63$ gives $w = \\frac{63}{1.05} = 60$. A common error is treating the two percentage changes as additive ($40\\% - 25\\% = 15\\%$), which gives $\\frac{63}{1.15} \\approx 54.78$. Another error is applying the $25\\%$ discount to the wholesale price rather than the marked-up retail price.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2S5QRVW', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of $250$ voters in a city found that $42\\%$ support a proposed transit plan, with a margin of error of $4\\%$. Which of the following is the best interpretation of this result?', NULL, $lyceon_json$[{"key":"A","text":"Between $38\\%$ and $46\\%$ of all voters in the city likely support the transit plan."},{"key":"B","text":"Exactly $42\\%$ of all voters in the city support the transit plan."},{"key":"C","text":"Between $38\\%$ and $46\\%$ of the $250$ voters surveyed support the transit plan."},{"key":"D","text":"The survey is unreliable because the margin of error is too large."}]$lyceon_json$::jsonb, 'A', NULL, E'A margin of error of $4\\%$ around a sample proportion of $42\\%$ produces a confidence interval of $38\\%$ to $46\\%$ for the entire population of city voters. Claiming exactly $42\\%$ support ignores sampling variability. Applying the interval to only the $250$ surveyed voters confuses the sample with the population — the margin of error describes uncertainty about the population parameter. Declaring the survey unreliable based solely on a $4\\%$ margin of error reflects a misunderstanding of what margins of error communicate.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2T4YVJE', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'For what value of $k$ does the following system of equations have no solution?
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2U03MG8', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'For what value of $k$ does $4x^2 - 12x + k = 0$ have exactly one real solution?', NULL, $lyceon_json$[{"key":"A","text":"$-9$"},{"key":"B","text":"$3$"},{"key":"C","text":"$9$"},{"key":"D","text":"$36$"}]$lyceon_json$::jsonb, 'C', NULL, E'A quadratic has exactly one real solution when the discriminant equals zero. For $4x^2 - 12x + k = 0$, the discriminant is $(-12)^2 - 4(4)(k) = 144 - 16k$. Setting $144 - 16k = 0$ gives $k = 9$. The value $-9$ applies an incorrect sign. The value $3$ results from computing $\\frac{12}{4} = 3$ rather than solving the discriminant equation. The value $36$ comes from dividing $144$ by $4$ instead of $16$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VF8181', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A recipe calls for $\\frac{5}{3}$ cups of sugar for every $\\frac{7}{2}$ cups of flour. If a baker uses $21$ cups of flour, how many cups of sugar does the baker need?', NULL, $lyceon_json$[{"key":"A","text":"$8$"},{"key":"B","text":"$10$"},{"key":"C","text":"$12$"},{"key":"D","text":"$15$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $10$. The ratio of sugar to flour is $\\frac{5/3}{7/2} = \\frac{5}{3} \\times \\frac{2}{7} = \\frac{10}{21}$. With $21$ cups of flour, the sugar needed is $\\frac{10}{21} \\times 21 = 10$ cups. The answer $8$ comes from an arithmetic error in simplifying the compound fraction. The answer $12$ results from setting up the proportion incorrectly by inverting only one of the fractions. The answer $15$ comes from multiplying $\\frac{5}{3} \\times \\frac{21}{7} = 5$ and then incorrectly tripling that result.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WOXE5G', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'grid_in', E'A shop sells two sizes of scented candles: small candles weigh 4 ounces each and large candles weigh 11 ounces each. A gift basket must contain at least 7 candles in total and must weigh no more than 50 ounces. What is the maximum number of large candles that can be in the basket?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '3', ARRAY['3'], E'Let $s$ represent the number of small candles and $l$ represent the number of large candles. The constraints are $s + l \\geq 7$ and $4s + 11l \\leq 50$, with $s \\geq 0$ and $l \\geq 0$. To maximize $l$, minimize $s$ by setting $s = 7 - l$ (the smallest value allowed by the first constraint). Substituting into the weight constraint: $4(7 - l) + 11l \\leq 50$, which simplifies to $28 - 4l + 11l \\leq 50$, then $7l \\leq 22$, so $l \\leq \\frac{22}{7} \\approx 3.14$. Since $l$ must be a whole number, the maximum is $l = 3$. Verification: with $l = 3$ and $s = 4$, the total is $4 + 3 = 7 \\geq 7$ candles and the weight is $4(4) + 11(3) = 16 + 33 = 49 \\leq 50$ ounces. Both constraints are satisfied.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XTOOQ4', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'In a right triangle, one of the acute angles measures $30^\\circ$ and the hypotenuse has length $22$. What is the length of the side opposite the $30^\\circ$ angle?', NULL, $lyceon_json$[{"key":"A","text":"$11$"},{"key":"B","text":"$11\\sqrt{2}$"},{"key":"C","text":"$11\\sqrt{3}$"},{"key":"D","text":"$\\frac{22\\sqrt{3}}{3}$"}]$lyceon_json$::jsonb, 'A', NULL, E'In a $30$-$60$-$90$ triangle, the side opposite the $30^\\circ$ angle is half the hypotenuse: $\\frac{22}{2} = 11$. The value $11\\sqrt{2}$ incorrectly applies the $45$-$45$-$90$ ratio (dividing by $\\sqrt{2}$) instead of the $30$-$60$-$90$ ratio. The value $11\\sqrt{3}$ is the length of the side adjacent to the $30^\\circ$ angle (opposite the $60^\\circ$ angle), not the side opposite $30^\\circ$. The value $\\frac{22\\sqrt{3}}{3}$ results from mistakenly computing $22 \\times \\tan(30^\\circ)$, conflating the tangent ratio with the sine ratio.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XZRGJH', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A jar contains $8$ red tokens, $13$ blue tokens, and $4$ yellow tokens. If one token is selected at random, what is the probability of selecting a blue token?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{13}{25}$"},{"key":"B","text":"$\\frac{13}{21}$"},{"key":"C","text":"$\\frac{8}{25}$"},{"key":"D","text":"$\\frac{4}{25}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total number of tokens is $8 + 13 + 4 = 25$. The probability of selecting a blue token is $\\frac{13}{25}$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YTPT7H', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a radius of $13$. What is the area of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$26\\pi$"},{"key":"B","text":"$144\\pi$"},{"key":"C","text":"$169\\pi$"},{"key":"D","text":"$676\\pi$"}]$lyceon_json$::jsonb, 'C', NULL, E'The area of a circle is $\\pi r^2 = \\pi(13)^2 = 169\\pi$. The value $26\\pi$ results from using the circumference formula $2\\pi r$ instead of the area formula. The value $144\\pi$ results from an arithmetic slip, squaring $12$ instead of $13$. The value $676\\pi$ results from squaring the diameter ($26^2 = 676$) instead of the radius.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZT0BEM', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'grid_in', E'The function $f$ is defined by $f(x) = -\\frac{7}{3}x + 18$. For what value of $x$ does $f(x) = 4$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '6', ARRAY['6'], E'Set $f(x) = 4$: $-\\frac{7}{3}x + 18 = 4$. Subtract $18$ from both sides: $-\\frac{7}{3}x = -14$. Multiply both sides by $-\\frac{3}{7}$: $x = -14 \\cdot (-\\frac{3}{7}) = \\frac{42}{7} = 6$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW22ONQCY', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'Researchers at the University of Konstanz recently discovered that European starlings adjust their migratory routes based on the geomagnetic field rather than solely relying on celestial cues. By fitting 47 starlings with miniature GPS loggers and exposing a subset to altered magnetic fields before release, the team found that birds subjected to magnetic manipulation deviated from the control group''s path by an average of 23 degrees. This deviation persisted even on overcast nights when stars were not visible, suggesting that the geomagnetic sense operates as a primary, not merely supplementary, navigation system.', $lyceon_json$[{"key":"A","text":"European starlings rely on the geomagnetic field as a primary navigation system during migration, not just as a backup to celestial cues."},{"key":"B","text":"Starlings fitted with GPS loggers traveled farther than those without loggers during the migration study."},{"key":"C","text":"Overcast skies prevent starlings from migrating effectively because they cannot see the stars."},{"key":"D","text":"The University of Konstanz developed a new type of GPS logger specifically for tracking small migratory birds."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer states that European starlings use the geomagnetic field as a primary navigation system, which captures the central finding described in the passage: birds with altered magnetic exposure deviated significantly from normal routes, even on overcast nights, indicating geomagnetic sensing is not merely supplementary. The claim about GPS loggers causing birds to travel farther misreads the study design, which used loggers for tracking, not as an experimental variable. The statement about overcast skies preventing effective migration contradicts the passage, which shows starlings navigated (albeit with deviation) even without visible stars. The claim about developing a new GPS logger focuses on a minor methodological detail rather than the study''s central finding.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23WZTP1', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Economists studying the medieval Champagne fairs have traditionally argued that these periodic markets flourished primarily because the Counts of Champagne guaranteed safe passage and enforced contracts, reducing transaction costs for merchants from across Europe. Recent archival work by Reyerson, however, reveals that many of the institutional protections attributed to the Counts were actually established by merchant guilds decades before comital authority expanded into commercial regulation. _______ the guilds'' contractual innovations — including standardized weights, multilateral clearing of debts, and notarized bills of exchange — emerged from practical necessity among traders rather than from top-down governance.', $lyceon_json$[{"key":"A","text":"In addition,"},{"key":"B","text":"That is,"},{"key":"C","text":"On the other hand,"},{"key":"D","text":"For instance,"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct transition is "That is," because the final sentence restates and clarifies Reyerson''s finding in more specific terms: the innovations came from practical merchant necessity, not from the Counts'' governance. It elaborates on the same point rather than introducing new information. "In addition" would signal supplementary information, but the final sentence explains the preceding claim rather than adding a separate one. "On the other hand" would introduce a contrasting viewpoint, yet the final sentence supports and unpacks the same revisionist argument Reyerson is making, not a competing one. "For instance" would introduce an example, but the final sentence is a restatement of the broader finding rather than a single illustrative case.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23XCORV', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'Seismologists have long relied on P-waves and S-waves to map Earth''s internal structure, since these waves change speed and direction as they pass through materials of different densities. In 2023, however, researchers at the Australian National University identified a previously undetected type of seismic wave — dubbed a "T-phase" — that travels along the boundary between the inner and outer core. _______ T-phase waves provide direct observational evidence for a distinct transition zone within the core that earlier models only predicted theoretically.', $lyceon_json$[{"key":"A","text":"In other words,"},{"key":"B","text":"By contrast,"},{"key":"C","text":"As a result,"},{"key":"D","text":"Granted,"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct transition is "As a result," because the final sentence describes a consequence of discovering T-phase waves: they provide direct evidence for a transition zone that was previously only theorized. The discovery leads to the evidential outcome. "In other words" would signal a restatement, but the final sentence introduces new information (observational evidence for a transition zone) rather than rephrasing the discovery. "By contrast" would signal opposition between the sentences, yet the final sentence builds on the discovery rather than contrasting with it. "Granted" would introduce a concession, but the passage does not concede a counterpoint.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW24551Q7', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'In a 2024 experiment, neuroscientists at the Karolinska Institute trained participants to associate specific odors with spatial locations in a virtual environment before sleep. During slow-wave sleep, the researchers re-exposed half the participants to those same odors without waking them. The re-exposed group recalled spatial locations with 31 percent greater accuracy the next morning than the control group. _______ the improvement vanished entirely when the odors were presented during REM sleep rather than slow-wave sleep, indicating that the consolidation benefit is phase-dependent rather than simply a product of nocturnal sensory exposure.', $lyceon_json$[{"key":"A","text":"Furthermore,"},{"key":"B","text":"Crucially,"},{"key":"C","text":"Similarly,"},{"key":"D","text":"Meanwhile,"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct transition is "Crucially," because the final sentence introduces a critical qualification to the preceding finding: the memory benefit is not simply caused by any nighttime odor exposure but depends specifically on the sleep phase. This is a pivotal detail that shapes interpretation of the result, making an emphasis marker appropriate. "Furthermore" would suggest an additional parallel finding, but the final sentence narrows and qualifies the original result rather than adding an independent one. "Similarly" would suggest the final sentence describes a comparable outcome, yet it actually describes a contrasting condition (REM sleep) that produced no benefit. "Meanwhile" would signal simultaneous events, but the sentence describes a follow-up experimental condition and its interpretive significance, not a concurrent occurrence.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW25E3GM1', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the main purpose of the text?', E'Historians have long treated the 1381 Peasants'' Revolt as a spontaneous eruption of agrarian discontent, but recent scholarship has complicated that narrative. Court records from Kent and Essex reveal that many of the revolt''s leaders were not impoverished laborers but prosperous tradespeople and minor officials who stood to lose influence under the new poll tax regime. Their grievances were less about hunger than about political exclusion from a system they had previously helped to administer. This reframing does not diminish the revolt''s significance; rather, it recasts the uprising as an act of political assertion by a class that saw its established role in local governance being eroded.', $lyceon_json$[{"key":"A","text":"To challenge a traditional interpretation of a historical event by presenting evidence for an alternative explanation"},{"key":"B","text":"To argue that economic hardship was not a factor in the 1381 Peasants' Revolt"},{"key":"C","text":"To compare the methods historians use to study medieval revolts with those used to study modern political movements"},{"key":"D","text":"To demonstrate that court records are a more reliable source than literary accounts for understanding medieval uprisings"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice about challenging a traditional interpretation by presenting an alternative explanation. The passage explicitly contrasts the long-held view of spontaneous agrarian discontent with recent evidence that the revolt''s leaders were prosperous tradespeople motivated by political exclusion. The choice claiming economic hardship was not a factor overstates the argument; the passage says grievances were "less about hunger," not that hunger was irrelevant. The choice about comparing historical methods is unsupported; the passage does not discuss methodological differences between medieval and modern scholarship. The choice about court records being more reliable than literary accounts introduces a comparison the passage never makes.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW25NBGY6', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'In 1847, the Hungarian physician Ignaz Semmelweis observed that mortality rates in the maternity ward staffed by doctors were nearly five times higher than in the ward staffed by midwives. He proposed that doctors were transferring "cadaverous particles" from the autopsy room to the delivery room on their unwashed hands. When he instituted mandatory hand-washing with chlorinated lime solution, the mortality rate in the doctors'' ward dropped from 18 percent to under 2 percent within three months. Despite this dramatic evidence, Semmelweis''s colleagues rejected his theory, dismissing it as incompatible with the prevailing miasma model of disease transmission.', $lyceon_json$[{"key":"A","text":"It presents a scientific observation, describes a proposed explanation and its supporting evidence, and then notes the response that explanation received"},{"key":"B","text":"It contrasts two competing theories of disease and evaluates the experimental evidence for each"},{"key":"C","text":"It narrates a physician's career in chronological order, emphasizing his most notable professional achievements"},{"key":"D","text":"It introduces a medical controversy and then argues that one side was definitively proven correct"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice describing the text as presenting an observation, a proposed explanation with evidence, and then the response it received. The passage moves from Semmelweis''s observation of mortality rates, to his hypothesis about unwashed hands and the evidence from chlorinated lime washing, to his colleagues'' rejection of the theory. The choice about contrasting two competing theories is inaccurate because the passage does not evaluate evidence for the miasma model; it only mentions the miasma view as the basis for rejection. The choice about narrating a career chronologically mischaracterizes the passage, which focuses on a single episode rather than a career overview. The choice about arguing one side was proven correct overstates the passage, which presents the rejection without declaring a definitive winner.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW26UDWCA', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 1, 'mcq', E'Based on the texts, how would the author of Text 2 most likely respond to the claim made in Text 1?', E'Text 1:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW26YJ1BQ', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The renovation of the Palazzo Ferrante, a project that the Italian Ministry of Culture initiated in 2019 after structural engineers warned of deterioration in the building''s eastern _____ uncovered a series of frescoes that art historians believe were painted by a previously unknown student of Pietro da Cortona.', $lyceon_json$[{"key":"A","text":"facade; has"},{"key":"B","text":"facade. Has"},{"key":"C","text":"facade, has"},{"key":"D","text":"facade has"}]$lyceon_json$::jsonb, 'C', NULL, E'A comma after "facade" is correct because it closes the nonrestrictive appositive phrase "a project that the Italian Ministry of Culture initiated in 2019 after structural engineers warned of deterioration in the building''s eastern facade," which was opened by the comma after "Ferrante." The subject of the sentence is "The renovation," and the main verb is "has uncovered"; the appositive provides additional information about the renovation and must be enclosed in a pair of commas. A semicolon after "facade" is incorrect because the text before the semicolon would not constitute an independent clause—"The renovation of the Palazzo Ferrante" lacks a verb. A period after "facade" is incorrect for the same reason: it would leave "The renovation of the Palazzo Ferrante, a project that...facade" as a fragment. Omitting punctuation altogether fails to close the appositive and produces an ungrammatical sentence.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW27HNX7Z', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which quotation from a literary critic, if accurate, would most directly support the claim made in the text about Otsuka''s narrative technique?', E'In her 2002 novel When the Emperor Was Divine, Julie Otsuka employs a conspicuous absence of proper names for her central characters, referring to them only by familial roles such as "the woman," "the boy," and "the girl." Some scholars have interpreted this technique as a purely aesthetic minimalism, but cultural historian Rena Masuyama contends that the namelessness is a deliberate rhetorical strategy: by stripping characters of individual names, Otsuka replicates the dehumanizing bureaucratic language of the internment orders that classified Japanese Americans as anonymous members of a suspect group rather than as distinct persons.', $lyceon_json$[{"key":"A","text":"\"Otsuka's unnamed characters echo the numbered tags and impersonal designations that the War Relocation Authority imposed on internees, collapsing the boundary between the government's documentary language and the novel's fictional register.\""},{"key":"B","text":"\"The spare prose style in When the Emperor Was Divine reflects Otsuka's admiration for Hemingway's iceberg theory, in which meaning is conveyed through what is left unsaid.\""},{"key":"C","text":"\"By withholding names, Otsuka invites readers to project their own identities onto the characters, a technique common in postmodern fiction that foregrounds reader participation.\""},{"key":"D","text":"\"Otsuka's use of familial titles instead of names creates an intimate domestic atmosphere that contrasts with the harshness of the internment camp setting.\""}]$lyceon_json$::jsonb, 'A', NULL, E'The quotation about numbered tags and the War Relocation Authority''s impersonal designations directly supports Masuyama''s claim that Otsuka''s namelessness replicates the dehumanizing bureaucratic language of internment orders. The quotation attributing the spare prose to Hemingway''s iceberg theory treats the technique as a general aesthetic choice, which aligns with the interpretation Masuyama is arguing against, not with her own claim. The suggestion that withholding names invites reader projection describes a postmodern literary device unrelated to the specific bureaucratic dehumanization Masuyama identifies. The observation about familial titles creating domestic intimacy acknowledges the technique but attributes a different rhetorical purpose (warmth and intimacy) rather than the dehumanizing replication of governmental language.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW28WMTDY', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Working with a team of graduate students, marine biologist Kenji Otsuka measured dissolved oxygen levels at seventeen deepwater stations in the Gulf of Bothnia _____ recorded temperature fluctuations at each site over a continuous forty-eight-hour sampling period.', $lyceon_json$[{"key":"A","text":"Bothnia, and recorded"},{"key":"B","text":"Bothnia; recorded"},{"key":"C","text":"Bothnia, recorded"},{"key":"D","text":"Bothnia and recorded"}]$lyceon_json$::jsonb, 'D', NULL, E'No comma before "and" is correct because "measured dissolved oxygen levels at seventeen deepwater stations in the Gulf of Bothnia" and "recorded temperature fluctuations at each site over a continuous forty-eight-hour sampling period" form a compound predicate sharing the single subject "Kenji Otsuka." A comma before a coordinating conjunction is used only when the conjunction joins two independent clauses, each with its own subject; in a compound predicate, no comma is needed. The choice inserting a comma before "and" incorrectly treats the compound predicate as a compound sentence. The choice using a semicolon without "and" improperly splits the predicate from its subject. The choice using only a comma without "and" produces a comma splice between what would appear to be two clauses, each lacking a conjunction.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 130, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW29NM4R0', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'As used in the text, what does the word "economy" most nearly mean?', E'The poet Marianne Moore was celebrated for the economy of her verse. Where contemporaries might elaborate a metaphor across an entire stanza, Moore compressed hers into a single, startling phrase, trusting her readers to expand the image without further prompting. Critics noted that this compression paradoxically generated a sense of abundance: each word performed the work of several, so that a short poem could feel densely populated with meaning.', $lyceon_json$[{"key":"A","text":"efficiency"},{"key":"B","text":"commerce"},{"key":"C","text":"prosperity"},{"key":"D","text":"regulation"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is "efficiency." The passage describes Moore compressing metaphors into single phrases so that each word does the work of several, which aligns with the idea of careful, sparing use of resources. "Commerce" refers to the buying and selling of goods, a common meaning of "economy" that has no relevance to poetic technique. "Prosperity" denotes wealth or financial success, which is unrelated to the passage''s focus on compression in verse. "Regulation" implies oversight or control of systems, which does not match the description of condensed poetic expression.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2EM1WA9', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support the researchers'' hypothesis?', E'Marine biologists at the Bermuda Institute of Ocean Sciences hypothesize that the decline in Sargassum seaweed mats in the western Sargasso Sea since 2017 is primarily caused by increased nutrient runoff from the Amazon River, which stimulates algal blooms that outcompete Sargassum for sunlight. To test this, the researchers compared satellite imagery of Sargassum coverage with measurements of dissolved nitrogen concentrations at various distances from the Amazon River plume.', $lyceon_json$[{"key":"A","text":"Areas closest to the Amazon River plume showed the highest dissolved nitrogen levels and the lowest Sargassum coverage."},{"key":"B","text":"Sargassum mats were thickest in regions with the warmest ocean surface temperatures."},{"key":"C","text":"Dissolved nitrogen concentrations in the Sargasso Sea have remained constant since 2010."},{"key":"D","text":"Algal bloom frequency has decreased in the Caribbean Sea over the past decade."}]$lyceon_json$::jsonb, 'A', NULL, E'The finding that areas closest to the Amazon plume had the highest nitrogen and lowest Sargassum directly supports the hypothesis that Amazon nutrient runoff drives algal competition that reduces Sargassum coverage. The finding about warm surface temperatures and thick Sargassum mats points to a different variable (temperature) unrelated to the nutrient runoff hypothesis. Constant nitrogen concentrations since 2010 would undermine, not support, the claim that increased runoff is responsible. Decreased algal blooms in the Caribbean would contradict the proposed mechanism of algal competition outcompeting Sargassum.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2EULKU5', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'While writing about the tardigrade for a biology presentation, a student wants to qualify a common claim about the organism''s resilience by introducing a nuance from recent research. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'While researching tardigrades for a biology presentation, a student has taken the following notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FCGRIY', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Archaeologist Fatima al-Rashid has excavated a network of underground cisterns beneath the ruins of a 9th-century trading settlement in the Rub'' al Khali desert. The cisterns, carved from sandstone bedrock, feature an intricate system of channels designed to capture and filter rainwater runoff from surrounding rock formations. Isotopic analysis of calcium carbonate deposits lining the cistern walls indicates that the cisterns held standing water for extended periods, yet the same isotopic data show that rainfall in the region during the 9th century was only marginally higher than today''s average of 35 millimeters per year. Al-Rashid argues that the settlement''s survival in such an arid environment depended less on climatic conditions than on ________', $lyceon_json$[{"key":"A","text":"the engineering sophistication of water capture infrastructure that maximized the utility of scarce rainfall."},{"key":"B","text":"long-distance trade networks that supplied the settlement with water transported from wetter regions."},{"key":"C","text":"a brief period of exceptionally heavy monsoon rains that filled the cisterns for decades."},{"key":"D","text":"the settlers' ability to extract groundwater from deep aquifers using drilling technology unavailable elsewhere."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage establishes that rainfall was only marginally higher than today''s minimal levels, yet the cisterns held water for extended periods. Combined with the description of intricate channels designed to capture and filter runoff, the logical completion is that the settlement relied on engineering sophistication to maximize scarce rainfall. The suggestion of water transported from wetter regions introduces an external supply mechanism not mentioned or implied by the passage''s focus on local water capture infrastructure. The claim about exceptionally heavy monsoon rains directly contradicts the isotopic evidence showing only marginally higher rainfall. The idea of deep aquifer drilling introduces technology the passage never references; the evidence points to surface runoff collection, not groundwater extraction.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2GTI63T', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'The painted lady butterfly undertakes one of the longest known insect migrations, traveling up to 15,000 kilometers between sub-Saharan Africa and Scandinavia across multiple generations. _______ this journey spans roughly six successive generations, with no single butterfly completing the entire route.', $lyceon_json$[{"key":"A","text":"Specifically,"},{"key":"B","text":"Nevertheless,"},{"key":"C","text":"Alternatively,"},{"key":"D","text":"Consequently,"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct transition is "Specifically," because the second sentence provides a more precise detail about the migration described in the first sentence — namely, that it spans six generations with no single butterfly completing it. This is a specification of the general claim. "Nevertheless" would signal a contrast, but the second sentence elaborates on rather than contradicts the first. "Alternatively" would introduce a different possibility, which is not the relationship here. "Consequently" would imply that the multigenerational nature is a result of the distance, but the passage presents it as a clarifying detail, not a causal outcome.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2HDXUSY', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'While writing about the Fuegian steamer duck for a wildlife magazine, a student wants to emphasize the bird''s unusual physical adaptation. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'While researching the Fuegian steamer duck, a student has taken the following notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2J61O01', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'As used in the text, what does the word "volatile" most nearly mean?', E'In a 2019 study of atmospheric methane concentrations over subarctic peatlands, researchers found that emission rates were remarkably volatile, shifting by as much as forty percent within a single diurnal cycle. The team attributed these rapid fluctuations to microbial communities whose metabolic activity responded almost instantly to changes in soil temperature and moisture levels.', $lyceon_json$[{"key":"A","text":"dangerous"},{"key":"B","text":"unpredictable"},{"key":"C","text":"explosive"},{"key":"D","text":"temporary"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is "unpredictable." The passage describes emission rates that shifted dramatically within a single day, and the context emphasizes rapid, irregular fluctuations rather than danger. "Dangerous" imposes a risk connotation absent from the passage. "Explosive" refers to a chemical property unrelated to rate variation. "Temporary" suggests the emissions would cease, but the passage describes ongoing variability, not brevity.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2JSZ1GB', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The collection of rare minerals on display at the Harkness Museum _____ specimens from every continent, including a 4.7-kilogram amethyst geode donated by a retired geologist in 2021.', $lyceon_json$[{"key":"A","text":"include"},{"key":"B","text":"includes"},{"key":"C","text":"are including"},{"key":"D","text":"have included"}]$lyceon_json$::jsonb, 'B', NULL, E'The singular verb "includes" is correct because the subject of the sentence is "collection," which is singular. The plural nouns "minerals" and "specimens" appear in prepositional phrases but do not determine the number of the verb. "Include," "are including," and "have included" are all plural verb forms that do not agree with the singular subject "collection."', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2K6AOR2', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best states the main idea of the text?', E'In a 2023 analysis of 1,340 fossilized pollen samples from sediment cores drilled in Lake Chalco, Mexico, paleoecologist Marta Caballero and her colleagues demonstrated that the Basin of Mexico experienced at least nine distinct episodes of extreme aridity between 27,000 and 4,000 years ago. Each arid phase lasted between 80 and 350 years and coincided with marked declines in arboreal pollen, particularly from pine and oak species, and corresponding surges in grass and composite pollen indicative of open, dry landscapes. Caballero''s team argues that these cyclical arid episodes were driven by shifts in the Intertropical Convergence Zone, which periodically redirected moisture-bearing winds away from central Mexico.', $lyceon_json$[{"key":"A","text":"Sediment cores from Lake Chalco provide evidence that the Basin of Mexico underwent repeated prolonged droughts linked to shifts in atmospheric circulation patterns."},{"key":"B","text":"Pine and oak trees were the dominant species in central Mexico for the majority of the past 27,000 years."},{"key":"C","text":"Fossilized pollen is the most reliable method for reconstructing ancient climates compared to other proxy records."},{"key":"D","text":"The Intertropical Convergence Zone has remained stable in its position over the past 27,000 years, rarely affecting Mexican rainfall patterns."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer captures the passage''s central idea: sediment core evidence reveals repeated arid episodes in the Basin of Mexico driven by atmospheric circulation shifts (specifically the Intertropical Convergence Zone). The claim that pine and oak trees were dominant for most of the 27,000-year period goes beyond the text, which only notes that arboreal pollen declined during arid phases without stating which species dominated overall. The assertion that fossilized pollen is the most reliable climate reconstruction method is an unsupported generalization; the passage uses pollen analysis but never compares it to other methods. The statement that the Intertropical Convergence Zone remained stable directly contradicts the passage, which describes periodic shifts in this zone as the driver of the arid episodes.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2KIZRHE', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The museum''s board of directors recommended that the institution _____ all acquisitions made between 2015 and 2020, a period during which the former acquisitions chair had allegedly circumvented standard provenance verification procedures.', $lyceon_json$[{"key":"A","text":"reexamines"},{"key":"B","text":"would reexamine"},{"key":"C","text":"reexamine"},{"key":"D","text":"will reexamine"}]$lyceon_json$::jsonb, 'C', NULL, E'The base form "reexamine" is correct because the verb "recommended" triggers the subjunctive mood in the "that" clause that follows it. In Standard English, verbs of recommendation, demand, and suggestion require the subjunctive—the bare infinitive form of the verb—regardless of the subject''s number. The indicative "reexamines" incorrectly applies third-person singular agreement as though the clause were a straightforward declarative statement. The conditional "would reexamine" improperly introduces a conditional construction where the subjunctive is required. The future "will reexamine" incorrectly treats the clause as a prediction rather than a recommendation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2KZCSIZ', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'By the time the excavation team reached the fourth stratum of the archaeological site in central Anatolia, they _____ more than twelve hundred pottery fragments, many of which displayed geometric patterns characteristic of the late Chalcolithic period.', $lyceon_json$[{"key":"A","text":"have recovered"},{"key":"B","text":"recovered"},{"key":"C","text":"were recovering"},{"key":"D","text":"had recovered"}]$lyceon_json$::jsonb, 'D', NULL, E'The past perfect "had recovered" is correct because the sentence describes an action (recovering fragments) that was completed before another past action (reaching the fourth stratum). The construction "by the time" followed by a simple past verb signals that the other clause requires the past perfect to establish the correct sequence of events. The present perfect "have recovered" is incorrect because it places the action in a time frame extending to the present, conflicting with the past-tense narrative. The simple past "recovered" fails to convey that the recovery was completed before the team reached the fourth stratum. The past progressive "were recovering" implies the action was ongoing rather than completed, which conflicts with the definite quantity "more than twelve hundred."', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
