INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2MQ6TPD', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'As used in the text, what does the word "tempered" most nearly mean?', E'Although the initial archaeological findings at the Denisova Cave in Siberia generated enormous excitement among paleoanthropologists, subsequent analysis tempered that enthusiasm considerably. Several bone fragments that had been attributed to a previously unknown hominin species were reclassified upon closer examination as belonging to known Neanderthal populations, reducing the scope of the original discovery.', $lyceon_json$[{"key":"A","text":"strengthened"},{"key":"B","text":"heated"},{"key":"C","text":"moderated"},{"key":"D","text":"forged"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is "moderated." The passage explains that subsequent analysis reduced enthusiasm by reclassifying some of the bone fragments, meaning excitement was restrained or toned down. "Strengthened" conveys the opposite meaning, suggesting enthusiasm increased. "Heated" refers to raising temperature, a literal sense of "temper" that does not fit the context of diminishing excitement. "Forged" relates to metalworking, another unrelated sense of the word.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2PNJC9C', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best states the main idea of the text?', E'Literary scholar Priya Natarajan has challenged the prevailing interpretation of Rabindranath Tagore''s 1910 novel Gora, which most critics read as an endorsement of cosmopolitan universalism over rigid Hindu nationalism. Natarajan contends that this reading flattens the novel''s structural complexity: Gora''s climactic renunciation of sectarian identity, she argues, is undermined by the narrative''s persistent association of moral authority with Brahmanical social codes. The protagonist''s final declaration of belonging to all of India, rather than resolving the novel''s ideological tensions, merely displaces them onto the figure of the subaltern characters, whose perspectives the novel systematically marginalizes. For Natarajan, the novel''s real achievement lies not in advocating universalism but in exposing the impossibility of transcending caste hierarchies through individual epiphany alone.', $lyceon_json$[{"key":"A","text":"Natarajan argues that Gora does not successfully endorse universalism but instead reveals how deeply caste hierarchies resist resolution through a single character's transformation."},{"key":"B","text":"Natarajan believes that Tagore intentionally wrote Gora to advocate for the preservation of Brahmanical social codes in Indian society."},{"key":"C","text":"Natarajan claims that most literary critics have correctly understood Gora as a novel about cosmopolitan universalism."},{"key":"D","text":"Natarajan suggests that the subaltern characters in Gora are the true protagonists whose perspectives drive the novel's central argument."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer accurately captures Natarajan''s central argument: the novel does not successfully advocate universalism because caste hierarchies cannot be transcended through one character''s epiphany. The claim that Tagore intentionally advocated for Brahmanical codes overstates Natarajan''s point; she argues the narrative inadvertently reinforces those codes, not that Tagore endorsed them deliberately. The suggestion that most critics have correctly understood the novel directly contradicts the passage, which states Natarajan is challenging the prevailing interpretation. The assertion that subaltern characters are the true protagonists misrepresents Natarajan''s argument; she notes their perspectives are marginalized, not that they function as protagonists driving the narrative.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2PXQ90I', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'While writing a report on sustainable architecture, a student wants to present a contrast between the environmental costs and benefits of green roofs. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'While researching green roofs for an environmental science class, a student has taken the following notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Q1XFX3', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which finding from the study, if true, would most directly weaken Okafor''s claim?', E'Sociologist Adaeze Okafor has argued that the rapid adoption of mobile banking in sub-Saharan Africa has reduced economic inequality within rural communities by giving small-scale farmers direct access to credit markets previously controlled by intermediaries. Okafor points to data from a 2021 survey of 3,200 farming households across seven countries showing that mobile banking users reported 31 percent higher annual income than non-users. Critics, however, have questioned whether the income difference reflects the effect of mobile banking itself or pre-existing economic advantages among early adopters.', $lyceon_json$[{"key":"A","text":"Farmers who adopted mobile banking earliest already had 28 percent higher incomes than non-adopters in the year before mobile banking became available in their regions."},{"key":"B","text":"Mobile banking platforms in sub-Saharan Africa charge transaction fees averaging 1.5 percent of each transfer."},{"key":"C","text":"The number of mobile banking users in sub-Saharan Africa doubled between 2019 and 2023."},{"key":"D","text":"Rural farmers in sub-Saharan Africa primarily use mobile banking to receive remittances from family members in urban areas."}]$lyceon_json$::jsonb, 'A', NULL, E'The finding that early adopters already had 28 percent higher incomes before mobile banking was available directly supports the critics'' concern about selection bias and weakens Okafor''s causal claim that mobile banking itself drove the income difference. Transaction fees of 1.5 percent are a cost detail that does not address whether the observed income gap results from mobile banking or pre-existing advantages. The doubling of users between 2019 and 2023 speaks to adoption rates, not to whether mobile banking reduces inequality. The observation about remittances describes a use pattern but does not challenge the claim that mobile banking increases income through credit access.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2QKX2L0', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'After analyzing fossilized pollen samples recovered from a peat bog near the village of Krupanj _____ botanist Yael Shimron concluded that the regional climate had shifted abruptly approximately 8,200 years ago. Her findings challenge the prevailing view that the area experienced a gradual transition between temperate and arid conditions.', $lyceon_json$[{"key":"A","text":"Krupanj, botanist"},{"key":"B","text":"Krupanj; botanist"},{"key":"C","text":"Krupanj. Botanist"},{"key":"D","text":"Krupanj botanist"}]$lyceon_json$::jsonb, 'A', NULL, E'A comma after "Krupanj" is correct because "After analyzing fossilized pollen samples recovered from a peat bog near the village of Krupanj" is an introductory prepositional phrase that must be set off from the main clause by a comma. A semicolon is incorrect because the introductory phrase is not an independent clause and therefore cannot stand on one side of a semicolon. A period is incorrect because it would turn the introductory phrase into a sentence fragment. Omitting punctuation entirely creates a run-on that obscures where the introductory phrase ends and the main clause begins.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2RKTXW5', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Entomologist Clara Duvall spent three field seasons tracking monarch butterfly migrations through the Appalachian corridor. Most researchers had assumed the butterflies followed a single, narrow _____ Duvall''s GPS-tagged specimens revealed that the insects dispersed across a band more than 130 kilometers wide, adjusting their paths in response to prevailing wind conditions.', $lyceon_json$[{"key":"A","text":"flyway, however, Duvall's"},{"key":"B","text":"flyway; however, Duvall's"},{"key":"C","text":"flyway, however Duvall's"},{"key":"D","text":"flyway however, Duvall's"}]$lyceon_json$::jsonb, 'B', NULL, E'A semicolon before "however" followed by a comma after it is the correct way to join two independent clauses with a conjunctive adverb. The choice using a comma before "however" and a comma after it produces a comma splice, because a comma alone cannot join two independent clauses even when a conjunctive adverb is present. The choice using a comma before "however" but omitting the comma after it compounds the comma-splice error with a missing comma after the conjunctive adverb. The choice omitting all punctuation before "however" creates a run-on sentence.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ROIDEG', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The hypothesis that the geometric motifs found on fragments of pottery from three separate Neolithic settlements in the Danube River basin _____ a shared symbolic vocabulary rather than coincidental similarities has gained considerable traction among archaeologists studying prehistoric communication networks.', $lyceon_json$[{"key":"A","text":"represent"},{"key":"B","text":"represents"},{"key":"C","text":"has represented"},{"key":"D","text":"representing"}]$lyceon_json$::jsonb, 'A', NULL, E'The plural verb "represent" is correct because the subject of the "that" clause is "motifs," which is plural. The sentence structure is "The hypothesis [that the geometric motifs... represent a shared symbolic vocabulary...] has gained traction"; within the noun clause, "motifs" governs the verb. The singular "represents" incorrectly matches the verb to "hypothesis" or to a nearer singular noun such as "basin," neither of which is the subject of the "that" clause. The singular present perfect "has represented" compounds the agreement error with an unnecessary tense shift. The participle "representing" is not a finite verb and would leave the "that" clause without a main verb, producing an ungrammatical sentence.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 130, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
