INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2TI84RP', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the underlined sentence in the text?', E'The fruit fly Drosophila melanogaster has been a staple of genetics research for over a century, valued for its short generation time and well-mapped genome. Recently, however, a team at the Okinawa Institute of Science and Technology turned to a less familiar organism: the mantis shrimp Odontodactylus scyllarus. <u>Unlike Drosophila, the mantis shrimp possesses sixteen types of photoreceptor cells, far exceeding the four found in most vertebrates.</u> The researchers hypothesized that studying such an elaborate visual system could reveal new mechanisms of color perception that simpler model organisms would never disclose.', $lyceon_json$[{"key":"A","text":"To explain why Drosophila has traditionally been preferred in genetics research"},{"key":"B","text":"To highlight a specific characteristic that makes the mantis shrimp a useful research subject"},{"key":"C","text":"To argue that vertebrate visual systems are insufficiently complex for scientific study"},{"key":"D","text":"To summarize the overall findings of the Okinawa research team"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is the choice stating that the sentence highlights a specific characteristic making the mantis shrimp a useful research subject. The underlined sentence presents the mantis shrimp''s sixteen photoreceptor types, distinguishing it from Drosophila and vertebrates, which directly supports the researchers'' reason for choosing this organism. The choice about Drosophila being preferred misidentifies the sentence''s focus, which is on the mantis shrimp, not on Drosophila. The choice about vertebrate insufficiency overstates the sentence; it provides a comparison but does not argue vertebrates are unfit for study. The choice about summarizing findings is inaccurate because the sentence describes a trait, not results.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2UXJ83J', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'Economists studying the labor market effects of automation have long predicted that routine manual jobs would be the first displaced by robotic systems. A 2024 study by the Brookings Institution, however, found that between 2015 and 2023, employment in routine manual occupations in the United States declined by only 4 percent, while employment in routine cognitive occupations -- such as data entry, bookkeeping, and insurance underwriting -- fell by 17 percent. The researchers attribute this disparity partly to the fact that physical manipulation in unstructured environments remains technically challenging for robots, whereas large language models and machine learning algorithms have become highly effective at pattern recognition and rule-based decision-making. This finding implies that ________', $lyceon_json$[{"key":"A","text":"advances in artificial intelligence have shifted the primary automation threat from manual labor to cognitive tasks that follow predictable patterns."},{"key":"B","text":"routine manual workers will never face significant displacement from automation because robots cannot operate in physical environments."},{"key":"C","text":"the Brookings Institution's methodology was flawed because it failed to account for job creation in new manual occupations."},{"key":"D","text":"large language models are more expensive to deploy than robotic systems, which explains why cognitive jobs were automated first."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage shows that cognitive occupations experienced much steeper employment declines than manual ones, and attributes this to AI''s effectiveness at pattern recognition versus robots'' difficulty with physical tasks. The logical inference is that AI has redirected the automation threat toward routine cognitive work. The claim that manual workers will never face displacement overstates the passage, which says physical manipulation is currently challenging for robots, not permanently impossible. The suggestion of methodological flaws is unsupported; the passage presents the Brookings findings without questioning their validity. The assertion about cost differences between language models and robotic systems introduces a factor the passage never mentions; the explanation given is technical capability, not cost.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2VCBNUL', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'Honeybees communicate the location of food sources through the "waggle dance," in which a forager bee performs a figure-eight pattern on the honeycomb. The angle of the dance relative to vertical indicates the direction of the food source relative to the sun, and the duration of the waggle phase correlates with the distance. Researchers have found, however, that bees raised in isolation without observing experienced foragers perform waggle dances that are significantly less precise in conveying distance information, although the directional component remains accurate. This suggests that ________', $lyceon_json$[{"key":"A","text":"the directional component of the waggle dance is innate, while the distance-signaling component is refined through social learning."},{"key":"B","text":"bees raised in isolation are unable to locate any food sources without assistance from experienced foragers."},{"key":"C","text":"the waggle dance evolved primarily as a mechanism for strengthening social bonds within the hive rather than for navigation."},{"key":"D","text":"experienced forager bees deliberately teach younger bees how to perform the waggle dance through repeated demonstrations."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage states that isolated bees retained accurate directional signaling but had imprecise distance signaling, which logically implies direction is innate while distance precision requires social learning from experienced foragers. The claim that isolated bees cannot locate any food goes far beyond the text, which only says their distance communication is less precise. The idea that the dance primarily strengthens social bonds has no support in the passage, which consistently frames the dance as a navigation tool. The assertion that foragers deliberately teach younger bees attributes intentional pedagogy that the passage does not describe; it only notes that exposure to experienced foragers improves precision.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
